import { describe, it, expect } from 'vitest';
import { Spc700Cpu, CYCLE_TABLE } from '../spc700-cpu.js';

/**
 * Expected values below are hand-computed from the real SPC700 instruction
 * semantics (transcribed in `spc700-cpu.ts` from blargg's `snes_spc`,
 * `~/Development/snes_spc/snes_spc/SPC_CPU.h`) -- fetch/decode/execute one
 * instruction against a known starting state and verify the exact resulting
 * state, not generated by running this project's own implementation and
 * copying its output (this project's established rigor, per
 * `snes-echo.test.ts`/`snes-dsp.test.ts`).
 */

function newCpu(): Spc700Cpu {
  const ram = new Uint8Array(0x10000);
  return new Spc700Cpu(ram, () => 0, () => {});
}

function loadProgram(cpu: Spc700Cpu, addr: number, bytes: number[]): void {
  for (let i = 0; i < bytes.length; i++) cpu.ram[addr + i] = bytes[i]!;
  cpu.reset(addr);
}

describe('CYCLE_TABLE', () => {
  it('matches known real per-opcode cycle counts (NOP=2, CALL=8, RET=5, MUL YA=9, DIV YA,X=12, MOV A,#imm=2)', () => {
    expect(CYCLE_TABLE[0x00]).toBe(2); // NOP
    expect(CYCLE_TABLE[0x3f]).toBe(8); // CALL
    expect(CYCLE_TABLE[0x6f]).toBe(5); // RET
    expect(CYCLE_TABLE[0xcf]).toBe(9); // MUL YA
    expect(CYCLE_TABLE[0x9e]).toBe(12); // DIV YA,X
    expect(CYCLE_TABLE[0xe8]).toBe(2); // MOV A,#imm
    expect(CYCLE_TABLE[0xf0]).toBe(4); // BEQ (taken cost; not-taken is 2 less, see below)
  });
});

describe('MOV A,#imm and NZ flags', () => {
  it('loading 0 sets Z, clears N', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x00]); // MOV A,#$00
    cpu.step();
    expect(cpu.a).toBe(0);
    expect(cpu.z).toBe(true);
    expect(cpu.n).toBe(false);
  });

  it('loading 0x80 clears Z, sets N', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x80]); // MOV A,#$80
    cpu.step();
    expect(cpu.a).toBe(0x80);
    expect(cpu.z).toBe(false);
    expect(cpu.n).toBe(true);
  });
});

describe('ADC A,#imm', () => {
  it('0x7F + 0x01 + carry-in 0 = 0x80: C clear, H set (nibble carry), V set (pos+pos=neg overflow)', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x7f, 0x88, 0x01]); // MOV A,#$7F; ADC A,#$01
    cpu.step();
    cpu.c = false;
    cpu.step();
    expect(cpu.a).toBe(0x80);
    expect(cpu.c).toBe(false);
    expect(cpu.h).toBe(true);
    expect(cpu.v).toBe(true);
    expect(cpu.n).toBe(true);
    expect(cpu.z).toBe(false);
  });

  it('0xFF + 0x01 + carry-in 0 = 0x00: C set (byte overflow), Z set, V clear (neg+pos=no signed overflow)', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0xff, 0x88, 0x01]); // MOV A,#$FF; ADC A,#$01
    cpu.step();
    cpu.c = false;
    cpu.step();
    expect(cpu.a).toBe(0x00);
    expect(cpu.c).toBe(true);
    expect(cpu.z).toBe(true);
    expect(cpu.v).toBe(false);
  });
});

describe('SBC A,#imm', () => {
  it('0x50 SBC #0x10 with carry set (no borrow-in) = 0x40, C stays set (no borrow)', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x50, 0xa8, 0x10]); // MOV A,#$50; SBC A,#$10
    cpu.step();
    cpu.c = true;
    cpu.step();
    expect(cpu.a).toBe(0x40);
    expect(cpu.c).toBe(true);
  });

  it('0x10 SBC #0x20 with carry set = 0xF0, C clears (borrow occurred)', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x10, 0xa8, 0x20]); // MOV A,#$10; SBC A,#$20
    cpu.step();
    cpu.c = true;
    cpu.step();
    expect(cpu.a).toBe(0xf0);
    expect(cpu.c).toBe(false);
    expect(cpu.n).toBe(true);
  });
});

describe('CMP A,#imm', () => {
  it('A=0x10 CMP #0x20: C clear (A<operand), N set, Z clear', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x10, 0x68, 0x20]); // MOV A,#$10; CMP A,#$20
    cpu.step();
    cpu.step();
    expect(cpu.c).toBe(false);
    expect(cpu.n).toBe(true);
    expect(cpu.z).toBe(false);
    expect(cpu.a).toBe(0x10); // CMP does not modify A
  });

  it('A=0x20 CMP #0x20: C set (A>=operand), Z set', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0xe8, 0x20, 0x68, 0x20]); // MOV A,#$20; CMP A,#$20
    cpu.step();
    cpu.step();
    expect(cpu.c).toBe(true);
    expect(cpu.z).toBe(true);
  });
});

describe('Direct page addressing (SETP/CLRP)', () => {
  it('SETP redirects dp-relative MOV to $01xx instead of $00xx', () => {
    const cpu = newCpu();
    // SETP; MOV $10,#$AB  (dp write) ; MOV A,$10 (dp read, should read the SAME dp-relative cell)
    loadProgram(cpu, 0x0200, [0x40, 0x8f, 0xab, 0x10, 0xe4, 0x10]);
    cpu.step(); // SETP
    expect(cpu.p).toBe(true);
    cpu.step(); // MOV $10,#$AB
    expect(cpu.ram[0x0110]).toBe(0xab); // landed in page 1, not page 0
    expect(cpu.ram[0x0010]).toBe(0x00);
    cpu.step(); // MOV A,$10
    expect(cpu.a).toBe(0xab);
  });
});

describe('Conditional branches', () => {
  it('BNE taken jumps by the signed relative offset and costs the full 4-cycle table entry', () => {
    const cpu = newCpu();
    // MOV A,#$01 (Z=false); BNE +2 (skip 2 bytes -- a NOP would sit there); NOP; NOP; MOV X,#$AA (target)
    loadProgram(cpu, 0x0200, [0xe8, 0x01, 0xd0, 0x02, 0x00, 0x00, 0xcd, 0xaa]);
    cpu.step(); // MOV A,#$01
    const cycles = cpu.step(); // BNE +2, taken
    expect(cycles).toBe(CYCLE_TABLE[0xd0]);
    expect(cpu.pc).toBe(0x0206);
    cpu.step(); // MOV X,#$AA
    expect(cpu.x).toBe(0xaa);
  });

  it('BNE not taken falls through and costs 2 cycles less than the table entry', () => {
    const cpu = newCpu();
    // MOV A,#$00 (Z=true); BNE +2 (not taken); MOV X,#$AA (falls through here)
    loadProgram(cpu, 0x0200, [0xe8, 0x00, 0xd0, 0x02, 0xcd, 0xaa]);
    cpu.step(); // MOV A,#$00
    const cycles = cpu.step(); // BNE +2, not taken
    expect(cycles).toBe(CYCLE_TABLE[0xd0]! - 2);
    expect(cpu.pc).toBe(0x0204);
    cpu.step(); // MOV X,#$AA
    expect(cpu.x).toBe(0xaa);
  });
});

describe('BRA (unconditional relative branch)', () => {
  /**
   * Regression test for a real shipped bug (`data-structure.md` §19.8): `BRA`
   * was written as the single expression `this.pc = (this.pc +
   * int8(this.fetch8())) & 0xffff`, and because JavaScript evaluates `+`'s
   * left operand first, `this.pc` was read *before* the operand fetch advanced
   * it — landing every `BRA` exactly one byte short. Every other relative
   * branch passes the fetch as a function argument (`this.branch(cond,
   * this.fetch8())`) and so read `pc` after the fetch, which is why only `BRA`
   * was affected and 20 other hand-computed instruction tests all passed. The
   * exact bytes below are a real driver's own `Main` loop site that exposed
   * it (ARAM `$02AC`: `2F 03`, whose real target is `$02B1`).
   */
  it('branches relative to the address AFTER the operand byte, not to the operand byte itself', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x02ac, [0x2f, 0x03]); // BRA +3
    const cycles = cpu.step();
    expect(cpu.pc).toBe(0x02b1); // $02AC + 2 (opcode+operand) + 3
    expect(cycles).toBe(CYCLE_TABLE[0x2f]);
  });

  it('branches backwards correctly for a negative offset', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0300, [0x2f, 0xfe]); // BRA -2 -> back onto itself
    cpu.step();
    expect(cpu.pc).toBe(0x0300); // $0300 + 2 - 2
  });
});

describe('16-bit ops (MOVW/ADDW)', () => {
  it('MOVW YA,dp loads A=low byte, Y=high byte, NZ from the combined word', () => {
    const cpu = newCpu();
    cpu.ram[0x0020] = 0x34;
    cpu.ram[0x0021] = 0x12;
    loadProgram(cpu, 0x0200, [0xba, 0x20]); // MOVW YA,$20
    cpu.step();
    expect(cpu.a).toBe(0x34);
    expect(cpu.y).toBe(0x12);
    expect(cpu.z).toBe(false);
    expect(cpu.n).toBe(false);
  });

  it('ADDW YA,dp: YA=0x00FF + word 0x0001 = 0x0100 (carry out of the low byte propagates into Y)', () => {
    const cpu = newCpu();
    cpu.ram[0x0020] = 0x01;
    cpu.ram[0x0021] = 0x00;
    cpu.reset(0x0200);
    cpu.a = 0xff;
    cpu.y = 0x00;
    cpu.ram[0x0200] = 0x7a; // ADDW YA,$20
    cpu.ram[0x0201] = 0x20;
    cpu.step();
    expect(cpu.a).toBe(0x00);
    expect(cpu.y).toBe(0x01);
  });
});

describe('Bit test/branch (BBS/BBC, SET1/CLR1)', () => {
  it('SET1 sets bit 3 of a dp cell; BBS on that bit branches', () => {
    const cpu = newCpu();
    // SET1 $10.3 (opcode 0x62); BBS $10.3,+2 (opcode 0x63); NOP; NOP; MOV X,#$5A
    loadProgram(cpu, 0x0200, [0x62, 0x10, 0x63, 0x10, 0x02, 0x00, 0x00, 0xcd, 0x5a]);
    cpu.step(); // SET1 $10.3
    expect(cpu.ram[0x0010] & 0x08).toBe(0x08);
    cpu.step(); // BBS $10.3,+2 -- relative offset is from the address right after the 3-byte instruction (0x0205), so +2 lands at 0x0207
    expect(cpu.pc).toBe(0x0207);
    cpu.step(); // MOV X,#$5A
    expect(cpu.x).toBe(0x5a);
  });
});

describe('AND1/OR1 (bit-indexed carry ops)', () => {
  it('AND1 C,mem.bit: carry ANDed with the addressed bit (13-bit packed operand: bits 0-12 = addr, bits 13-15 = bit index)', () => {
    const cpu = newCpu();
    cpu.ram[0x0050] = 0x08; // bit 3 set
    // AND1 C,$0050.3 -- opcode 0x4A, operand = addr | (bit<<13) = 0x0050 | (3<<13) = 0x6050
    loadProgram(cpu, 0x0200, [0x80, 0x4a, 0x50, 0x60]); // SETC; AND1 C,$0050.3
    cpu.step(); // SETC
    cpu.step(); // AND1 C,$0050.3 -- bit 3 of $0050 is set, so C stays true
    expect(cpu.c).toBe(true);
  });

  it('OR1 C,mem.bit sets carry when the addressed bit is set, even if carry started clear', () => {
    const cpu = newCpu();
    cpu.ram[0x0050] = 0x08;
    loadProgram(cpu, 0x0200, [0x60, 0x0a, 0x50, 0x60]); // CLRC; OR1 C,$0050.3
    cpu.step();
    cpu.step();
    expect(cpu.c).toBe(true);
  });
});

describe('TCALL / vector table', () => {
  it('TCALL 0 (opcode 0x01) jumps through the vector at $FFDE and pushes the real return address', () => {
    const cpu = newCpu();
    cpu.ram[0xffde] = 0x00;
    cpu.ram[0xffdf] = 0x03; // vector -> $0300
    cpu.ram[0x0300] = 0xcd; // MOV X,#$77
    cpu.ram[0x0301] = 0x77;
    cpu.ram[0x0302] = 0x6f; // RET
    loadProgram(cpu, 0x0200, [0x01, 0xcd, 0x11]); // TCALL 0; MOV X,#$11 (return lands here)
    cpu.step(); // TCALL 0
    expect(cpu.pc).toBe(0x0300);
    cpu.step(); // MOV X,#$77
    expect(cpu.x).toBe(0x77);
    cpu.step(); // RET
    expect(cpu.pc).toBe(0x0201);
    cpu.step(); // MOV X,#$11
    expect(cpu.x).toBe(0x11);
  });
});

describe('PUSH PSW / POP PSW round trip', () => {
  it('preserves all flags across a push/pop', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0x0d, 0x60, 0x8e]); // PUSH PSW; CLRC (scramble c); POP PSW
    // Set flags AFTER loadProgram/reset() (reset() itself clears all flags to their power-on state).
    cpu.n = true;
    cpu.v = true;
    cpu.z = false;
    cpu.c = true;
    cpu.h = true;
    cpu.step(); // PUSH PSW
    cpu.step(); // CLRC
    expect(cpu.c).toBe(false);
    cpu.step(); // POP PSW
    expect(cpu.n).toBe(true);
    expect(cpu.v).toBe(true);
    expect(cpu.z).toBe(false);
    expect(cpu.c).toBe(true);
    expect(cpu.h).toBe(true);
  });
});

describe('Subroutine call/return', () => {
  it('CALL pushes the return address; RET pops it back, resuming right after the CALL', () => {
    const cpu = newCpu();
    // CALL $0210; MOV X,#$11 (return lands here); ... at $0210: MOV Y,#$22; RET
    loadProgram(cpu, 0x0200, [0x3f, 0x10, 0x02, 0xcd, 0x11]);
    cpu.ram[0x0210] = 0x8d; // MOV Y,#$22
    cpu.ram[0x0211] = 0x22;
    cpu.ram[0x0212] = 0x6f; // RET
    cpu.step(); // CALL $0210
    expect(cpu.pc).toBe(0x0210);
    cpu.step(); // MOV Y,#$22
    expect(cpu.y).toBe(0x22);
    cpu.step(); // RET
    expect(cpu.pc).toBe(0x0203); // right after the 3-byte CALL instruction
    cpu.step(); // MOV X,#$11
    expect(cpu.x).toBe(0x11);
  });
});

describe('forceCall', () => {
  it('pushes the given return address and jumps to the target; a real RET at the target resumes at the return address', () => {
    const cpu = newCpu();
    cpu.ram[0x0300] = 0xcd; // MOV X,#$99
    cpu.ram[0x0301] = 0x99;
    cpu.ram[0x0302] = 0x6f; // RET
    cpu.reset(0x0400);
    cpu.forceCall(0x0300, 0x0400);
    expect(cpu.pc).toBe(0x0300);
    cpu.step(); // MOV X,#$99
    expect(cpu.x).toBe(0x99);
    cpu.step(); // RET
    expect(cpu.pc).toBe(0x0400);
  });
});

describe('MUL YA / DIV YA,X', () => {
  it('MUL YA: Y=0x80, A=0x02 -> product 0x0100, A=0x00, Y=0x01', () => {
    const cpu = newCpu();
    cpu.reset(0x0200);
    cpu.y = 0x80;
    cpu.a = 0x02;
    cpu.ram[0x0200] = 0xcf; // MUL YA
    cpu.step();
    expect(cpu.a).toBe(0x00);
    expect(cpu.y).toBe(0x01);
  });

  it('DIV YA,X: YA=0x0064 (100), X=0x0A (10) -> A=quotient 10, Y=remainder 0', () => {
    const cpu = newCpu();
    cpu.reset(0x0200);
    cpu.y = 0x00;
    cpu.a = 0x64;
    cpu.x = 0x0a;
    cpu.ram[0x0200] = 0x9e; // DIV YA,X
    cpu.step();
    expect(cpu.a).toBe(10);
    expect(cpu.y).toBe(0);
  });
});

describe('PSW flag ops', () => {
  it('SETC/CLRC/NOTC toggle the carry flag directly', () => {
    const cpu = newCpu();
    loadProgram(cpu, 0x0200, [0x80, 0xed, 0x60]); // SETC; NOTC; CLRC
    cpu.step();
    expect(cpu.c).toBe(true);
    cpu.step();
    expect(cpu.c).toBe(false);
    cpu.step();
    expect(cpu.c).toBe(false);
  });
});
